import nodemailer from "nodemailer";
import { db } from "./db";
import { decryptSecret } from "./crypto-box";
import { mayDeliverTo, type NotifyKind } from "./prefs";
import {
  renderTemplate,
  recordEmail,
  wrapEmail,
  emailButton,
  appUrl,
  emailHeading,
  emailParagraph,
  emailEyebrow,
  emailNote,
  emailPanel,
  emailBanner,
  emailKeyValue,
  type Accent,
} from "./email-render";
import { renderInvoiceHTML, invoiceBranding, formatInvoiceNumber } from "./invoices";
import { emails as catalogEmails, type BuiltEmail } from "./email-templates";

/**
 * SMTP config comes from the Setting table (admin-editable) with env fallback.
 * Keys: smtp_host, smtp_port, smtp_user, smtp_pass, smtp_from, smtp_secure.
 * If nothing is configured, falls back to a local sendmail/Postfix relay on :25.
 */
/**
 * The stored SMTP password, decrypted — tolerating a LEGACY plaintext row.
 *
 * `smtp_pass` is now written through `encryptSecret` (iv:tag:ciphertext), but a
 * value saved before that change is bare plaintext. `decryptSecret` returns null
 * on a value that is not in the encrypted shape, so a null result means "this was
 * never encrypted" — fall back to the raw stored value. Once an operator re-saves
 * the SMTP settings, the row is encrypted and this fallback stops being taken.
 */
function smtpPassPlain(stored: string | undefined): string {
  if (!stored) return "";
  const dec = decryptSecret(stored);
  return dec ?? stored;
}

async function loadSmtp() {
  const rows = await db.setting.findMany({
    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_from", "smtp_secure"] } },
  });
  const s = Object.fromEntries(rows.map((r) => [r.key, r.value]));
  const host = s.smtp_host || process.env.SMTP_HOST || "";
  const from = s.smtp_from || process.env.SMTP_FROM || `Nxeon <no-reply@${(process.env.APP_URL ?? "localhost").replace(/^https?:\/\//, "")}>`;
  return {
    host,
    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
    user: s.smtp_user || process.env.SMTP_USER || "",
    pass: smtpPassPlain(s.smtp_pass) || process.env.SMTP_PASS || "",
    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
    from,
  };
}

export async function mailConfigured(): Promise<boolean> {
  const c = await loadSmtp();
  return !!c.host || process.env.NXEON_LOCAL_MAIL === "1";
}

function transport(c: Awaited<ReturnType<typeof loadSmtp>>) {
  if (!c.host) {
    // Local MTA fallback (Postfix/sendmail on the host)
    return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
  }
  // When the SMTP host is an internal IP (e.g. the mail VM at 10.20.0.10) but the
  // server presents a cert for its hostname (mail.nxeon.cloud), TLS validation
  // fails on an IP mismatch. `SMTP_TLS_SERVERNAME` lets us keep cert verification
  // on while telling TLS the name to validate against (and sets SNI accordingly).
  const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
  return nodemailer.createTransport({
    host: c.host,
    port: c.port,
    secure: c.secure,
    auth: c.user ? { user: c.user, pass: c.pass } : undefined,
    ...(servername ? { tls: { servername } } : {}),
  });
}

/** Template keys whose emails ship the itemised invoice as an attachment. */
const INVOICE_ATTACH_TEMPLATES = new Set(["receipt", "invoice_new", "renewal_reminder"]);

export type MailAttachment = { filename: string; content: string | Buffer; contentType?: string };

/**
 * Build the invoice attachment for an email. There is no PDF library installed
 * (and we can't add dependencies), so we attach the branded, print-ready
 * invoice HTML produced by `lib/invoices.ts` — recipients open it and use their
 * browser's Print → Save as PDF, matching the on-site download route.
 */
async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
  try {
    const invoice = await db.invoice.findUnique({
      where: { id: invoiceId },
      include: { user: { select: { name: true, email: true } } },
    });
    if (!invoice) return null;
    // Use the SAME branding the dashboard and the download route use, so the
    // invoice a customer receives by email carries the identifier they can quote
    // back at you — and the seller block, which only reaches emailed invoices
    // through this path. Previously this hardcoded `#00012`-style numbering while
    // every on-screen copy showed `INV-00012`: the customer and the support agent
    // would have been reading two different invoice numbers for one invoice.
    const branding = await invoiceBranding();
    const html = renderInvoiceHTML(invoice, invoice.user, branding);
    const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
    return { filename: `nxeon-invoice-${number}.html`, content: html, contentType: "text/html; charset=utf-8" };
  } catch (e) {
    console.error("[mailer] failed to build invoice attachment:", e);
    return null;
  }
}

export type SendMailOpts = {
  to: string;
  /** Optional Reply-To (e.g. route a contact-form reply straight to the sender). */
  replyTo?: string;
  /** Explicit subject. Optional when `template` is provided. */
  subject?: string;
  /** Explicit pre-rendered HTML. Optional when `template` is provided. */
  html?: string;
  text?: string;
  /** DB template key — when set (and no explicit `html`), the body is rendered via `renderTemplate`. */
  template?: string;
  /** Variables for `{{placeholders}}` when rendering from a template. */
  vars?: Record<string, unknown>;
  /** Attribution for the EmailLog row. */
  userId?: string | null;
  /** When set, attaches the invoice (auto for receipt/invoice_new/renewal_reminder templates). */
  invoiceId?: string;
  /** Extra attachments. */
  attachments?: MailAttachment[];
  /**
   * What KIND of message this is, for the notification-preference policy in
   * `lib/prefs.ts`. Supply it together with `userId` and this function enforces
   * the customer's choice centrally — see the gate below.
   *
   * Omitting it means "always send", which is the safe default: a message must
   * never be dropped because someone forgot to classify it.
   */
  kind?: NotifyKind;
};

/**
 * Send an email. Never throws — logs and returns false on failure so callers
 * don't break flows. EVERY attempt is written to `EmailLog` (SENT on success,
 * FAILED + error otherwise) for the admin Logs viewer.
 *
 * NOTIFICATION PREFERENCES are enforced HERE, not at the call sites.
 * `User.notificationPrefs` was a column the customer edited and nothing read, so
 * turning off "email me about billing" changed nothing. Gating each send site
 * individually would have fixed today's sites and left every future one to
 * re-introduce the bug; gating centrally means a new send site inherits the
 * policy automatically and per-site checks become defence in depth.
 *
 * Two deliberate properties, both fail-open:

 * Two deliberate properties, both fail-open:
 *   - no `kind` (or no `userId`) → send. Unclassified is never silenced.
 *   - `mayDeliverTo` returns true for anything non-suppressible without touching
 *     the database, and also on a lookup error. A payment-failure or suspension
 *     warning must not be lost because a preference read failed.
 */
export async function sendMail(opts: SendMailOpts): Promise<boolean> {
  // Preference gate. CRITICAL kinds (payment failed, suspension, security
  // changes, data loss…) are declared non-suppressible in lib/prefs.ts and short
  // -circuit to true, so this costs nothing on the paths that matter most.
  if (opts.kind && opts.userId) {
    const allowed = await mayDeliverTo(opts.userId, opts.kind, "email");
    if (!allowed) {
      console.log(`[mail] suppressed ${opts.kind} to user ${opts.userId} by preference`);
      return false;
    }
  }

  // Resolve subject/html: prefer explicit values, otherwise render the template.
  let subject = opts.subject ?? "";
  let html = opts.html ?? "";
  const templateKey = opts.template ?? null;

  if (templateKey && !opts.html) {
    const rendered = await renderTemplate(templateKey, opts.vars ?? {});
    subject = opts.subject ?? rendered.subject;
    html = rendered.html;
  }

  // Assemble attachments (invoice auto-attaches for the relevant templates).
  const attachments: MailAttachment[] = [...(opts.attachments ?? [])];
  const wantInvoice = opts.invoiceId && (!templateKey || INVOICE_ATTACH_TEMPLATES.has(templateKey));
  if (wantInvoice && opts.invoiceId) {
    const att = await invoiceAttachment(opts.invoiceId);
    if (att) attachments.push(att);
  }

  try {
    const c = await loadSmtp();
    if (!c.host && process.env.NXEON_LOCAL_MAIL !== "1") {
      console.warn("[mailer] not configured — skipping email:", subject);
      await recordEmail(opts.to, subject, templateKey, html, "FAILED", "SMTP not configured", opts.userId);
      return false;
    }
    const t = transport(c);
    await t.sendMail({
      from: c.from,
      to: opts.to,
      replyTo: opts.replyTo || undefined,
      subject,
      html,
      text: opts.text ?? html.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim(),
      attachments: attachments.length ? attachments : undefined,
    });
    await recordEmail(opts.to, subject, templateKey, html, "SENT", null, opts.userId);
    return true;
  } catch (e) {
    console.error("[mailer] send failed:", e);
    await recordEmail(opts.to, subject, templateKey, html, "FAILED", String((e as Error)?.message ?? e), opts.userId);
    return false;
  }
}

/**
 * Preferred path for DB-templated sends: render `key` with `vars`, send, log,
 * and (for billing templates) attach the invoice. Thin convenience over
 * `sendMail` for new callers.
 *
 * `kind` is forwarded to `sendMail`, which is the ONLY place the notification
 * policy is enforced. It used to be absent from this signature, so every send
 * routed through this wrapper was structurally incapable of honouring the
 * customer's "Account email" preference — a caller could not have opted in even
 * if it wanted to. That is the same class of defect as the column nothing read
 * (see `sendMail`), just one layer up: the gate exists, and the convenient path
 * quietly walks around it. Omitting `kind` still means "always send".
 */
export async function sendTemplate(
  key: string,
  to: string,
  vars: Record<string, unknown> = {},
  opts: {
    userId?: string | null;
    invoiceId?: string;
    attachments?: MailAttachment[];
    kind?: NotifyKind;
  } = {},
): Promise<boolean> {
  return sendMail({
    to,
    template: key,
    vars,
    userId: opts.userId,
    invoiceId: opts.invoiceId,
    attachments: opts.attachments,
    kind: opts.kind,
  });
}

export async function sendTestMail(to: string): Promise<{ ok: boolean; error?: string }> {
  try {
    const c = await loadSmtp();
    const t = transport(c);
    const html = layout("SMTP test", "<p>Your Nxeon mail configuration works. 🎉</p>");
    await t.sendMail({ from: c.from, to, subject: "Nxeon SMTP test", html });
    await recordEmail(to, "Nxeon SMTP test", null, html, "SENT");
    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: String(e?.message ?? e).slice(0, 300) };
  }
}

const BRAND = { blue: "#3b82f6", purple: "#8a70fb", bg: "#0a101f", card: "#111a30" };

/**
 * Shared responsive email shell (inline styles for client compatibility).
 * Kept for the synchronous, code-rendered `emails.*` templates below and any
 * existing importers. DB-template sends use `wrapEmail` in `lib/email-render`.
 */
export function layout(title: string, body: string): string {
  // Delegate to the shared premium shell so every email is consistent.
  const heading = title
    ? `<h1 style="margin:0 0 16px;font-size:21px;font-weight:700;color:#ffffff;line-height:1.25;">${title}</h1>`
    : "";
  return wrapEmail(`${heading}<div>${body}</div>`);
}

export function button(href: string, label: string): string {
  return emailButton(href, label);
}

// ---- Transactional templates ----
//
// The full transactional catalog lives in `lib/email-templates.ts` (30+
// templates, all composed from the shared inline-styled components). It is
// re-exported here as `emails` so every existing call site — `import { emails }
// from "@/lib/mailer"` — keeps working unchanged. Each entry returns
// `{ template, subject, html }`; the six original signatures are preserved.
export type { BuiltEmail };

// ===========================================================================
// Card billing & dunning templates
//
// Renewals apply wallet credit first, then auto-charge the customer's saved
// card for the remainder. When that charge fails we retry on day 1, 3 and 5 and
// only suspend once the retries are exhausted. These templates carry that flow.
//
// They live here rather than in `lib/email-templates.ts` only because this file
// is the one owned by the card-billing change; they are built with the same
// `build()` shape and the same shared components, so they render identically to
// the rest of the catalog.
// ===========================================================================

/**
 * Number of automatic retries in the dunning sequence (day 1, day 3, day 5).
 * `paymentRetryFailed` uses it to tell the customer how many attempts are left,
 * so the worker's retry schedule and this copy must agree.
 */
export const DUNNING_RETRY_ATTEMPTS = 3;

/**
 * Same composition helper as `lib/email-templates.ts` (which keeps its copy

476 lib/invoices.ts
import { db } from "@/lib/db";
import { getSetting, SETTINGS_DEFAULTS } from "@/lib/settings";
import { brandLabel } from "@/lib/stripe-cards";
import type { Invoice, InvoiceStatus, Prisma, User } from "@prisma/client";

/**
 * Seller identity + number prefix printed on an invoice, resolved from Settings →
 * General/Billing. Read once per render and handed to the (synchronous) renderer.
 */
export type InvoiceBranding = {
  /** `invoice_prefix`, never blank — see `invoiceBranding()`. */
  numberPrefix: string;
  /** `brand_name`, never blank. */
  brandName: string;
  /** `company_legal_name` — "" means "omit the seller block". */
  legalName: string;
  /** `company_address` — "" means "omit the seller address". */
  address: string;
};

const FALLBACK_BRANDING: InvoiceBranding = {
  numberPrefix: SETTINGS_DEFAULTS.invoice_prefix,
  brandName: SETTINGS_DEFAULTS.brand_name,
  legalName: "",
  address: "",
};

/**
 * Read the invoice branding from Settings.
 *
 * `numberPrefix` is forced non-empty. `Invoice.number` is a bare autoincrement, so an
 * operator who clears the field would otherwise produce documents identified only as
 * "00012" — not quotable to a customer, not greppable in a mailbox, and impossible to
 * tell apart from a server ID or an order number in a support thread.
 *
 * `legalName`/`address` stay blank-able by design: the seller block is omitted entirely
 * when they are unset, rather than printing an empty "From" heading. That is why the
 * "shown on invoices" claim on the admin field is now true without the panel having to
 * demand a value it does not have.
 */
export async function invoiceBranding(): Promise<InvoiceBranding> {
  const [prefix, brandName, legalName, address] = await Promise.all([
    getSetting("invoice_prefix"),
    getSetting("brand_name"),
    getSetting("company_legal_name"),
    getSetting("company_address"),
  ]);
  return {
    numberPrefix: prefix.trim() || SETTINGS_DEFAULTS.invoice_prefix,
    brandName: brandName.trim() || SETTINGS_DEFAULTS.brand_name,
    legalName: legalName.trim(),
    address: address.trim(),
  };
}

/**
 * The customer-facing invoice identifier: the configured prefix plus the zero-padded
 * autoincrement (`INV-00012`).
 *
 * One function so every surface agrees. The padding was previously duplicated as
 * `#${String(n).padStart(5, "0")}` at eight call sites, which is precisely why
 * `invoice_prefix` had no reader — there was no single place to wire it. The `#` sigil
 * is dropped now that a prefix is always present; keeping both would render `#INV-00012`.
 */
export function formatInvoiceNumber(
  number: number,
  prefix: string = SETTINGS_DEFAULTS.invoice_prefix,
): string {
  return `${prefix}${String(number).padStart(5, "0")}`;
}

/**
 * Invoice line item shape stored in `Invoice.lineItems` (Json).
 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
 * is used as a fallback when a line omits it.
 */
export type LineItem = {
  description: string;
  qty: number;
  unitCents: number;
  amountCents: number;
};

export function coerceLineItems(raw: unknown): LineItem[] {
  if (!Array.isArray(raw)) return [];
  return raw
    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
    .map((x) => {
      const qty = Number(x.qty ?? 1) || 0;
      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
      const amountCents = Math.round(
        Number(x.amountCents ?? qty * unitCents) || 0
      );
      return {
        description: String(x.description ?? "Item"),
        qty,
        unitCents,
        amountCents,
      };
    });
}

/** Compute subtotal / tax / total (all integer cents) for an invoice. */
export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
  const items = coerceLineItems(invoice.lineItems);
  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
  const taxCents = invoice.taxCents ?? 0;
  // `amountCents` is the stored authoritative total; fall back to computed.
  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
  return { items, subtotalCents, taxCents, totalCents };
}

const STATUS_LABEL: Record<InvoiceStatus, string> = {
  OPEN: "Open",
  PAID: "Paid",
  VOID: "Void",
  REFUNDED: "Refunded",
};

export function invoiceStatusLabel(status: InvoiceStatus): string {

export function invoiceStatusLabel(status: InvoiceStatus): string {
  return STATUS_LABEL[status] ?? status;
}

/**
 * Human-readable payment method / status line for an invoice.
 *
 * PAID/REFUNDED → "Paid with Visa •••• 4242 on Aug 3, 2026", using the stamped
 * card snapshot (`paidBrand`/`paidLast4`). For invoices issued before the snapshot
 * existed those are null, so we FALL BACK to the user's current card fields —
 * historical invoices still read correctly. If no card is known at all we show a
 * plain "Paid …". OPEN → "Awaiting payment"; VOID → "Void".
 */
export function invoicePaymentMethod(
  invoice: Pick<Invoice, "status" | "paidAt" | "paidBrand" | "paidLast4">,
  fallbackCard?: { cardBrand: string | null; cardLast4: string | null } | null,
): string {
  if (invoice.status === "OPEN") return "Awaiting payment";
  if (invoice.status === "VOID") return "Void";

  const brand = invoice.paidBrand ?? fallbackCard?.cardBrand ?? null;
  const last4 = invoice.paidLast4 ?? fallbackCard?.cardLast4 ?? null;
  const verb = invoice.status === "REFUNDED" ? "Refunded" : "Paid";
  const when = invoice.paidAt ? ` on ${fmtDate(invoice.paidAt)}` : "";
  if (last4) return `${verb} with ${brandLabel(brand)} •••• ${last4}${when}`;
  return `${verb}${when}`;
}

export type InvoiceInput = {
  userId: string;
  description: string;
  lineItems: LineItem[];
  taxCents?: number;
  status?: InvoiceStatus;
  period?: { start?: Date | null; end?: Date | null };
  /**
   * Card snapshot to stamp when this invoice is created already PAID (renewals,
   * auto-charges). Ignored for non-PAID invoices. Null-safe: a user with no saved
   * card leaves these null and the UI falls back to their current card fields.
   */
  paidBrand?: string | null;
  paidLast4?: string | null;
};

/**
 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
 * a charge site can create the invoice inside its own guarded `$transaction`
 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
 * The stored total (`amountCents`) is always derived from line items + tax so
 * callers can't desync the stamped total from the itemised breakdown.
 */
export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
  const items = opts.lineItems.map((li) => ({
    description: String(li.description),
    qty: Number(li.qty) || 0,
    unitCents: Math.round(Number(li.unitCents) || 0),
    amountCents: Math.round(
      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
    ),
  }));
  const taxCents = Math.round(opts.taxCents ?? 0);
  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
  const amountCents = subtotalCents + taxCents;
  const status = opts.status ?? "OPEN";

  return {
    userId: opts.userId,
    description: opts.description,
    lineItems: items,
    taxCents,
    amountCents,
    status,
    paidAt: status === "PAID" ? new Date() : null,
    // Only stamp the paying card on invoices born PAID; an OPEN invoice has not
    // been charged to any card yet.
    paidBrand: status === "PAID" ? opts.paidBrand ?? null : null,
    paidLast4: status === "PAID" ? opts.paidLast4 ?? null : null,
    periodStart: opts.period?.start ?? null,
    periodEnd: opts.period?.end ?? null,
  };
}

/**
 * Create an Invoice row directly. The total (`amountCents`) is derived from the
 * line items plus tax so callers can't accidentally desync the stamped total
 * from the itemised breakdown.
 */
export async function createInvoice(opts: InvoiceInput): Promise<Invoice> {
  return db.invoice.create({ data: invoiceCreateData(opts) });
}

function esc(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function money(cents: number): string {
  const neg = cents < 0;
  return `${neg ? "−" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
}

function fmtDate(d: Date | null | undefined): string {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
  PAID: { color: "#10b981", label: "PAID" },
  OPEN: { color: "#f59e0b", label: "OPEN" },
  VOID: { color: "#64748b", label: "VOID" },
  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
};

/**
 * Render a clean, print-ready branded HTML invoice. Intended to be served
 * standalone (users Print → Save as PDF — see the download route).
 *
 * `branding` is optional and defaults to the built-in values so this stays synchronous
 * and every existing caller keeps compiling. Async callers should pass
 * `await invoiceBranding()`; a caller that does not will render the platform defaults
 * (`INV-`, "Nxeon", no seller block) — identical to the pre-wiring output, never a blank.
 */
export function renderInvoiceHTML(
  invoice: Invoice,
  user: Pick<User, "name" | "email">,
  branding: InvoiceBranding = FALLBACK_BRANDING,
): string {
  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
  const stamp = STATUS_STAMP[invoice.status] ?? STATUS_STAMP.OPEN;
  const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
  const period =
    invoice.periodStart || invoice.periodEnd
      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
      : null;

  const rows = items
    .map(
      (li) => `
      <tr>
        <td class="desc">${esc(li.description)}</td>
        <td class="num">${esc(li.qty)}</td>
        <td class="num">${money(li.unitCents)}</td>
        <td class="num">${money(li.amountCents)}</td>
      </tr>`
    )
    .join("");

  const logo = `
    <svg width="34" height="34" viewBox="0 0 40 40" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <defs>
        <linearGradient id="nxg" x1="0" y1="0" x2="40" y2="40" gradientUnits="userSpaceOnUse">
          <stop stop-color="#3b82f6"/>
          <stop offset="1" stop-color="#6f47f5"/>
        </linearGradient>
      </defs>
      <rect width="40" height="40" rx="10" fill="url(#nxg)"/>
      <path d="M11 28V12h3.2l9.4 10.6V12H27v16h-3.2L14.4 17.4V28H11Z" fill="#fff"/>
    </svg>`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>${esc(branding.brandName)} Invoice ${esc(number)}</title>
<style>
  :root { color-scheme: light; }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: #f1f5f9;
    color: #0f172a;
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    font-size: 14px;
    line-height: 1.5;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  .sheet {
    max-width: 760px;
    margin: 32px auto;
    background: #fff;
