import PDFDocument from "pdfkit";
import type { Invoice, InvoiceStatus, User } from "@prisma/client";
import { brandLabel } from "@/lib/stripe-cards";
import {
  invoiceTotals,
  formatInvoiceNumber,
  type InvoiceBranding,
} from "@/lib/invoices";

/**
 * Server-side PDF renderer for invoices — the REAL, downloadable/attachable PDF
 * that accounting departments need, replacing the print-ready HTML that only
 * produced a PDF via the customer's browser (Print → Save as PDF).
 *
 * `pdfkit` is a pure-JS generator: no headless Chromium, no system libraries and
 * no font files (the standard Helvetica family is embedded), so it runs headless
 * on the server inside a Next.js route/action. It draws imperatively, which lets
 * this file mirror the branded HTML in `renderInvoiceHTML` — the same gradient
 * bar, logo mark, From/Billed-to blocks, itemised table, subtotal/tax/total and
 * status stamp — so a customer's emailed PDF matches the on-screen invoice.
 *
 * This renders ONLY; it reuses `invoiceTotals` / `formatInvoiceNumber`, so it
 * never derives or restates a charge amount — the money core is untouched.
 */

const BRAND_BLUE = "#3b82f6";
const BRAND_PURPLE = "#6f47f5";
const INK = "#0f172a";
const MUTED = "#64748b";
const FAINT = "#94a3b8";
const HAIRLINE = "#e2e8f0";
const ROW_LINE = "#f1f5f9";

// Mirror of the (module-private) STATUS_STAMP in lib/invoices.ts.
const STATUS_STAMP: Record<InvoiceStatus, { color: string; label: string }> = {
  PAID: { color: "#10b981", label: "PAID" },
  OPEN: { color: "#f59e0b", label: "OPEN" },
  VOID: { color: "#64748b", label: "VOID" },
  REFUNDED: { color: "#8a70fb", label: "REFUNDED" },
};

function money(cents: number): string {
  const neg = cents < 0;
  return `${neg ? "-" : ""}$${(Math.abs(cents) / 100).toFixed(2)}`;
}

function fmtDate(d: Date | null | undefined): string {
  if (!d) return "—";
  return new Date(d).toLocaleDateString("en-US", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
}

/**
 * Render the branded invoice as a real PDF and resolve to a Buffer.
 *
 * `branding` is required here (unlike the synchronous HTML renderer) because the
 * only callers — the download route and the mailer — already resolve it via
 * `invoiceBranding()`, so the seller block is always available.
 */
export function renderInvoicePDF(
  invoice: Invoice,
  user: Pick<User, "name" | "email">,
  branding: InvoiceBranding,
): Promise<Buffer> {
  const { items, subtotalCents, taxCents, totalCents } = invoiceTotals(invoice);
  const stamp = STATUS_STAMP[invoice.status] ?? STATUS_STAMP.OPEN;
  const number = formatInvoiceNumber(invoice.number, branding.numberPrefix);
  const period =
    invoice.periodStart || invoice.periodEnd
      ? `${fmtDate(invoice.periodStart)} – ${fmtDate(invoice.periodEnd)}`
      : null;

  const doc = new PDFDocument({
    size: "A4",
    margin: 40,
    info: {
      Title: `${branding.brandName} Invoice ${number}`,
      Author: branding.brandName,
      Subject: invoice.description,
    },
  });

  const chunks: Buffer[] = [];
  const done = new Promise<Buffer>((resolve, reject) => {
    doc.on("data", (c: Buffer) => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
  });

  const left = doc.page.margins.left; // 40
  const right = doc.page.width - doc.page.margins.right;
  const contentW = right - left;

  // --- Top gradient bar (matches the HTML .bar) ---
  const bar = doc.linearGradient(left, 0, right, 0);
  bar.stop(0, BRAND_BLUE).stop(1, BRAND_PURPLE);
  doc.rect(0, 0, doc.page.width, 6).fill(bar);

  let y = 56;

  // --- Header: logo + brand (left), invoice number + stamp (right) ---
  // Logo mark: rounded square with the brand gradient and a white "N".
  const logoSize = 34;
  const logoGrad = doc.linearGradient(left, y, left + logoSize, y + logoSize);
  logoGrad.stop(0, BRAND_BLUE).stop(1, BRAND_PURPLE);
  doc.roundedRect(left, y, logoSize, logoSize, 10).fill(logoGrad);
  doc
    .fillColor("#ffffff")
    .font("Helvetica-Bold")
    .fontSize(22)
    .text("N", left, y + 6, { width: logoSize, align: "center" });

  const brandX = left + logoSize + 12;
  doc
    .fillColor(INK)
    .font("Helvetica-Bold")
    .fontSize(20)
    .text(branding.brandName, brandX, y + 1);
  doc
    .fillColor(MUTED)
    .font("Helvetica")
    .fontSize(11)
    .text("Cloud VPS Hosting", brandX, y + 25);

  // Right meta block.
  doc
    .fillColor(MUTED)
    .font("Helvetica")
    .fontSize(11)
    .text("Invoice", left, y, { width: contentW, align: "right" });
  doc
    .fillColor(INK)
    .font("Helvetica-Bold")
    .fontSize(22)
    .text(number, left, y + 15, { width: contentW, align: "right" });

  // Status stamp: bordered coloured pill, right-aligned under the number.
  const stampLabel = stamp.label;
  doc.font("Helvetica-Bold").fontSize(11);
  const stampTextW = doc.widthOfString(stampLabel);
  const stampPadX = 10;
  const stampW = stampTextW + stampPadX * 2;
  const stampH = 20;
  const stampX = right - stampW;
  const stampY = y + 44;
  doc
    .lineWidth(1.5)
    .roundedRect(stampX, stampY, stampW, stampH, 6)
    .strokeColor(stamp.color)
    .stroke();
  doc
    .fillColor(stamp.color)
    .text(stampLabel, stampX, stampY + 5, { width: stampW, align: "center", characterSpacing: 1 });

  y = 132;

  // --- Parties row (From / Billed to / Issued / Service period) ---
  const showSeller = !!(branding.legalName || branding.address);
  type Party = { label: string; lines: { text: string; muted?: boolean }[] };
  const parties: Party[] = [];
  if (showSeller) {
    const lines: Party["lines"] = [];
    if (branding.legalName) lines.push({ text: branding.legalName });
    if (branding.address)
      branding.address.split(/\r?\n/).forEach((l) => lines.push({ text: l, muted: true }));
    parties.push({ label: "From", lines });
  }
  parties.push({
    label: "Billed to",
    lines: [{ text: user.name ?? "—" }, { text: user.email ?? "", muted: true }],
  });
  const issuedLines: Party["lines"] = [{ text: fmtDate(invoice.createdAt) }];
  if (invoice.paidAt) issuedLines.push({ text: `Paid ${fmtDate(invoice.paidAt)}`, muted: true });
  if (invoice.paidLast4)
    issuedLines.push({
      text: `${brandLabel(invoice.paidBrand)} ···· ${invoice.paidLast4}`,
      muted: true,
    });
  parties.push({ label: "Issued", lines: issuedLines });
  if (period) parties.push({ label: "Service period", lines: [{ text: period }] });

  // Two columns so a From + Billed-to + Issued + period set wraps cleanly on A4.
  const colGap = 24;
  const colW = (contentW - colGap) / 2;
  let maxRowBottom = y;
  parties.forEach((p, i) => {
    const col = i % 2;
    const rowStart = y + Math.floor(i / 2) * 62;
    const px = left + col * (colW + colGap);
    let py = rowStart;
    doc
      .fillColor(FAINT)
      .font("Helvetica-Bold")
      .fontSize(8)
      .text(p.label.toUpperCase(), px, py, { width: colW, characterSpacing: 0.5 });
    py += 12;
    p.lines.forEach((ln) => {
      doc
        .fillColor(ln.muted ? MUTED : INK)
        .font(ln.muted ? "Helvetica" : "Helvetica-Bold")
        .fontSize(ln.muted ? 10 : 11)
        .text(ln.text, px, py, { width: colW });
      py += ln.muted ? 13 : 15;
    });
    maxRowBottom = Math.max(maxRowBottom, py);
  });

  y = maxRowBottom + 24;

  // --- Line-item table ---
  // Columns: Description (flex), Qty, Unit, Amount (right-aligned numerics).
  const colQtyW = 50;
  const colUnitW = 80;
  const colAmtW = 90;
  const colDescW = contentW - colQtyW - colUnitW - colAmtW;
  const xDesc = left;
  const xQty = xDesc + colDescW;
  const xUnit = xQty + colQtyW;
  const xAmt = xUnit + colUnitW;

  const header = (label: string, x: number, w: number, align: "left" | "right") =>
    doc.fillColor(FAINT).font("Helvetica-Bold").fontSize(8).text(label.toUpperCase(), x, y, {
      width: w,
      align,
      characterSpacing: 0.5,
    });
  header("Description", xDesc, colDescW, "left");
  header("Qty", xQty, colQtyW, "right");
  header("Unit", xUnit, colUnitW, "right");
  header("Amount", xAmt, colAmtW, "right");
  y += 14;
  doc.moveTo(left, y).lineTo(right, y).lineWidth(1).strokeColor(HAIRLINE).stroke();
  y += 10;

  const drawRow = (desc: string, qty: string, unit: string, amount: string) => {
    // Page-break guard: keep rows on the page.
    if (y > doc.page.height - 140) {
      doc.addPage();
      y = 56;
    }
    const descH = doc.font("Helvetica").fontSize(10).heightOfString(desc, { width: colDescW });
    doc.fillColor(INK).font("Helvetica").fontSize(10).text(desc, xDesc, y, { width: colDescW });
    doc.fillColor(INK).text(qty, xQty, y, { width: colQtyW, align: "right" });
    doc.text(unit, xUnit, y, { width: colUnitW, align: "right" });
    doc.text(amount, xAmt, y, { width: colAmtW, align: "right" });
    const rowH = Math.max(descH, 12) + 12;
    y += rowH;
    doc.moveTo(left, y - 4).lineTo(right, y - 4).lineWidth(1).strokeColor(ROW_LINE).stroke();
  };

  if (items.length === 0) {
    drawRow(invoice.description, "", "", money(totalCents));
  } else {
    for (const li of items) {
      drawRow(li.description, String(li.qty), money(li.unitCents), money(li.amountCents));
    }
  }

  // --- Totals (right-aligned block) ---
  y += 12;
  const totalsW = 220;
  const totalsX = right - totalsW;
  const kW = totalsW - colAmtW;
  const totalRow = (k: string, v: string, opts: { bold?: boolean; rule?: boolean } = {}) => {
    if (opts.rule) {
      doc.moveTo(totalsX, y).lineTo(right, y).lineWidth(1.5).strokeColor(INK).stroke();
      y += 8;
    }
    doc
      .fillColor(opts.bold ? INK : MUTED)
      .font(opts.bold ? "Helvetica-Bold" : "Helvetica")
      .fontSize(opts.bold ? 14 : 10)
      .text(k, totalsX, y, { width: kW });
    doc
      .fillColor(INK)
      .font(opts.bold ? "Helvetica-Bold" : "Helvetica")
      .fontSize(opts.bold ? 14 : 10)
      .text(v, totalsX + kW, y, { width: colAmtW, align: "right" });
    y += opts.bold ? 22 : 16;
  };
  totalRow("Subtotal", money(subtotalCents));
  totalRow("Tax", money(taxCents));
  totalRow("Total", money(totalCents), { bold: true, rule: true });
  if (invoice.refundedCents > 0) totalRow("Refunded", `-${money(invoice.refundedCents)}`);

  // --- Footer ---
  const footY = doc.page.height - 70;
  if (y < footY) {
    doc.moveTo(left, footY).lineTo(right, footY).lineWidth(1).strokeColor(HAIRLINE).stroke();
    doc
      .fillColor(FAINT)
      .font("Helvetica")
      .fontSize(9)
      .text(invoice.description, left, footY + 10, { width: contentW * 0.6 });
    doc.text(`${branding.brandName} · Thank you for your business`, left, footY + 10, {
      width: contentW,
      align: "right",
    });
  }

  doc.end();
  return done;
}

/**
 * Filename used everywhere a PDF is served/attached, so the download and the
 * email carry the same, quotable name (e.g. `nxeon-invoice-INV-00012.pdf`).
 */
export function invoicePdfFilename(number: number, prefix: string): string {
  return `nxeon-invoice-${formatInvoiceNumber(number, prefix)}.pdf`;
}

import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { invoiceBranding } from "@/lib/invoices";
import { renderInvoicePDF, invoicePdfFilename } from "@/lib/invoice-pdf";

/**
 * Streams the invoice as a REAL, server-rendered PDF (see lib/invoice-pdf.ts).
 *
 * This is the download counterpart of the HTML route in `../route.ts`; it mirrors
 * that route's guards EXACTLY — authenticated, and the caller must own the invoice
 * or be an admin — so the PDF is never a way to read another customer's billing.
 */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const invoice = await db.invoice.findUnique({
    where: { id },
    include: { user: { select: { name: true, email: true } } },
  });
  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });

  const isOwner = invoice.userId === user.id;
  const isAdmin = user.role === "ADMIN";
  if (!isOwner && !isAdmin) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  const branding = await invoiceBranding();
  const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
  const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);

  // Uint8Array view keeps NextResponse's BodyInit happy across runtimes.
  return new NextResponse(new Uint8Array(pdf), {
    status: 200,
    headers: {
      "Content-Type": "application/pdf",
      "Content-Disposition": `attachment; filename="${filename}"`,
      "Content-Length": String(pdf.length),
      "Cache-Control": "private, no-store",
    },
  });
}

