/**
 * Build the invoice attachment for an email. We now attach a REAL PDF, rendered
 * server-side by `lib/invoice-pdf.ts` (pdfkit — pure JS, no headless browser),
 * so accounting departments receive an actual `application/pdf` document rather
 * than the print-ready HTML that only became a PDF via the recipient's browser.
 * It carries the same branded layout and identifier as the on-site PDF download.
 */
async function invoiceAttachment(invoiceId: string): Promise<MailAttachment | null> {
  try {
    const invoice = await db.invoice.findUnique({
      where: { id: invoiceId },
      include: { user: { select: { name: true, email: true } } },
    });
    if (!invoice) return null;
    // Use the SAME branding the dashboard and the download route use, so the
    // invoice a customer receives by email carries the identifier they can quote
    // back at you — and the seller block, which only reaches emailed invoices
    // through this path. Previously this hardcoded `#00012`-style numbering while
    // every on-screen copy showed `INV-00012`: the customer and the support agent
    // would have been reading two different invoice numbers for one invoice.
    const branding = await invoiceBranding();
    const pdf = await renderInvoicePDF(invoice, invoice.user, branding);
    const filename = invoicePdfFilename(invoice.number, branding.numberPrefix);
    return { filename, content: pdf, contentType: "application/pdf" };
  } catch (e) {
    console.error("[mailer] failed to build invoice attachment:", e);
    return null;
  }
}

import { renderInvoicePDF, invoicePdfFilename } from "@/lib/invoice-pdf";

// pdfkit relies on Node APIs (streams, fs-backed font metrics), so pin this
// route to the Node.js runtime rather than the Edge runtime.
export const runtime = "nodejs";

